```c
/*
 * Camera privacy switch
 *
 * On several Lenovo consumer models (e.g. Legion 5 15ACH6H / 82JU) the EC
 * exposes the position of the camera privacy switch twice:
 *
 *  - as an absolute firmware bit ("CAMS"), which gates the camera's USB port
 *    and is readable through the ACPI _STA of the camera port child device
 *    (\_SB.PCI0.GP17.XHC0.RHUB.HSP3.CAMA); and
 *  - as a firmware event pushed through the "Lenovo Utility Key Press Event"
 *    WMI interface (GUID 8FC0DE0C-B4E4-43FD-B0F3-8871711C1294), where the
 *    event values 0x0c / 0x0d mean "camera switch on" / "camera switch off".
 *
 * The event value is the raw value returned by the firmware's _WED method for
 * the LSK notification (notify id 0xd0), see the DSDT.
 */
static char *camera_switch_path = "\\_SB.PCI0.GP17.XHC0.RHUB.HSP3.CAMA";
module_param(camera_switch_path, charp, 0444);
MODULE_PARM_DESC(camera_switch_path,
		 "ACPI path of the camera-privacy child device; its _STA method returns 0x0f when the camera is enabled, 0 when the privacy switch has disabled it (default: \\_SB.PCI0.GP17.XHC0.RHUB.HSP3.CAMA).");

#define IDEAPAD_CAMERA_SWITCH_EVENT_ON  0x0c
#define IDEAPAD_CAMERA_SWITCH_EVENT_OFF 0x0d
#define IDEAPAD_CAMERA_SWITCH_POLL_MS   2000

/*
 * Read the absolute switch state from firmware.  Returns 0 and sets @on on
 * success.  Read-only: the _STA method just returns the firmware bit.
 */
static int ideapad_camera_switch_read(struct ideapad_private *priv, bool *on)
{
	unsigned long long status;
	acpi_status ret;

	if (!priv->camera_switch_handle)
		return -ENODEV;

	ret = acpi_evaluate_integer(priv->camera_switch_handle, "_STA", NULL, &status);
	if (ACPI_FAILURE(ret))
		return -EIO;

	*on = !!(status & 0x0f);
	return 0;
}

static void ideapad_camera_switch_report(struct ideapad_private *priv, bool on)
{
	if (priv->camera_switch_reported && priv->camera_switch_on == on)
		return;

	priv->camera_switch_on = on;
	priv->camera_switch_reported = true;

	dev_dbg(&priv->platform_device->dev, "camera switch: camera %s\n",
		str_on_off(on));

	input_report_switch(priv->inputdev, SW_CAMERA_LENS_COVER, !on);
	input_sync(priv->inputdev);
}
```
