/*
 * Camera privacy switch
 *
 * The EC reports the position of the camera privacy switch through the
 * "Lenovo Utility Key Press Event" WMI class (GUID
 * 8FC0DE0C-B4E4-43FD-B0F3-8871711C1294): event value 0x0c means the switch was
 * moved to "camera on" and 0x0d to "camera off".  These are the values the
 * firmware's _WED returns for notify 0xd0 (see the DSDT), and they were
 * confirmed on a Legion 5 15ACH6H (82JU) by moving the switch.
 *
 * The switch acts by cutting the camera's USB connection, so the absolute
 * state is likewise observable on the USB bus.  Presence is used to seed the
 * initial value and as a slow safety net for missed events.
 *
 * Note: the firmware "CAMS" bit, reachable as the ACPI _STA of
 * \_SB.PCI0.GP17.XHC0.RHUB.HSP3.CAMA, does *not* follow the switch at runtime
 * (measured on 82JU: it stays 0x0f while the switch has the camera
 * disconnected).  It only describes whether the port is enabled for ACPI
 * enumeration at boot, so it is used here purely as a capability probe and is
 * never read as state.
 */
#define IDEAPAD_CAMERA_SWITCH_EVENT_ON	0x0c
#define IDEAPAD_CAMERA_SWITCH_EVENT_OFF	0x0d

/* Number of consecutive agreeing USB-presence samples before a change is
 * adopted; the WMI event normally reacts immediately, this only has to catch
 * lost events without being fooled by transient USB re-enumeration.
 */
#define IDEAPAD_CAMERA_POLL_MS		2000
#define IDEAPAD_CAMERA_POLL_CONFIRM	2

static ushort camera_usb_vendor = 0x04f2;
module_param(camera_usb_vendor, ushort, 0444);
MODULE_PARM_DESC(camera_usb_vendor,
		 "USB vendor ID of the internal camera (default 0x04f2)");

static ushort camera_usb_product = 0xb725;
module_param(camera_usb_product, ushort, 0444);
MODULE_PARM_DESC(camera_usb_product,
		 "USB product ID of the internal camera (default 0xb725)");

static int ideapad_camera_usb_match(struct usb_device *udev, void *data)
{
	bool *found = data;

	if (le16_to_cpu(udev->descriptor.idVendor) == camera_usb_vendor &&
	    le16_to_cpu(udev->descriptor.idProduct) == camera_usb_product) {
		*found = true;
		return 1;	/* stop iterating */
	}

	return 0;
}

static bool ideapad_camera_present(void)
{
	bool found = false;

	usb_for_each_dev(&found, ideapad_camera_usb_match);

	return found;
}

