static void ideapad_camera_switch_poll(struct work_struct *work)
{
	struct ideapad_private *priv = container_of(to_delayed_work(work),
						    struct ideapad_private,
						    camera_switch_work);
	bool present;

	if (!priv->camera_switch_active)
		return;

	present = ideapad_camera_present();

	if (!priv->camera_switch_reported) {
		ideapad_camera_switch_report(priv, present);
	} else if (present == priv->camera_switch_on) {
		priv->camera_switch_mismatch = 0;
	} else if (++priv->camera_switch_mismatch >=
		   IDEAPAD_CAMERA_POLL_CONFIRM) {
		dev_dbg(&priv->platform_device->dev,
			"camera switch: no event, adopting USB presence\n");
		ideapad_camera_switch_report(priv, present);
	}

	if (priv->camera_switch_active)
		schedule_delayed_work(&priv->camera_switch_work,
				      msecs_to_jiffies(IDEAPAD_CAMERA_POLL_MS));
}

static void ideapad_camera_switch_setup(struct ideapad_private *priv)
{
	acpi_handle handle;
	acpi_status ret;

	/*
	 * The presence of the camera port's child device in the ACPI namespace
	 * is used as the capability probe: it exists on models whose camera
	 * port is privacy-gated.  Its _STA is *not* used as state (see above).
	 */
	ret = acpi_get_handle(NULL, camera_switch_path, &handle);
	if (ACPI_FAILURE(ret)) {
		dev_info(&priv->platform_device->dev,
			 "camera privacy switch not available (%s: %s)\n",
			 camera_switch_path, acpi_format_exception(ret));
		return;
	}

	priv->camera_switch_supported = true;
	INIT_DELAYED_WORK(&priv->camera_switch_work,
			  ideapad_camera_switch_poll);

	dev_info(&priv->platform_device->dev,
		 "camera privacy switch reporting enabled (%s)\n",
		 camera_switch_path);
}

static void ideapad_camera_switch_start(struct ideapad_private *priv)
{
	if (!priv->camera_switch_supported)
		return;

	ideapad_camera_switch_report(priv, ideapad_camera_present());

	priv->camera_switch_active = true;
	schedule_delayed_work(&priv->camera_switch_work,
			      msecs_to_jiffies(IDEAPAD_CAMERA_POLL_MS));
}

static void ideapad_camera_switch_stop(struct ideapad_private *priv)
{
	if (!priv->camera_switch_supported)
		return;

	priv->camera_switch_active = false;
	cancel_delayed_work_sync(&priv->camera_switch_work);
}

